import {ActionMenu} from '@primer/react'
import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'

import styles from './BudgetsTable.module.css'
import loadingStyles from './BudgetsLoadingTable.module.css'

const SKELETON_ROW_COUNT = 5

type Props = {
  isCustomerTable?: boolean
  customerTableLabel?: string
  isEnterpriseRoute?: boolean
  showScopeSelector?: boolean
  selectedScope?: string
}

function SkeletonRow() {
  return (
    <tr className={loadingStyles.SkeletonRow}>
      <td className={loadingStyles.SkeletonTargetCell}>
        <div className={loadingStyles.SkeletonIconContainer}>
          <LoadingSkeleton width="16px" height="16px" variant="rounded" />
        </div>
        <div className={loadingStyles.SkeletonTargetInfo}>
          <div className={loadingStyles.SkeletonDataCell}>
            <LoadingSkeleton width="80px" height="14px" />
            <LoadingSkeleton width="120px" height="16px" className={loadingStyles.SkeletonTextWithMargin} />
          </div>
        </div>
      </td>
      <td className={loadingStyles.SkeletonPricingTypeCell}>
        <div className={loadingStyles.SkeletonDataCell}>
          <LoadingSkeleton width="50px" height="14px" />
          <LoadingSkeleton width="100px" height="16px" className={loadingStyles.SkeletonTextWithMargin} />
        </div>
      </td>
      <td className={loadingStyles.SkeletonStopUsageCell}>
        <div className={loadingStyles.SkeletonDataCell}>
          <LoadingSkeleton width="70px" height="14px" />
          <LoadingSkeleton width="30px" height="16px" className={loadingStyles.SkeletonTextWithMargin} />
        </div>
      </td>
      <td className={loadingStyles.SkeletonProgressCell}>
        <div className={loadingStyles.SkeletonProgressContainer}>
          <div className={loadingStyles.SkeletonProgressRow}>
            <div className={loadingStyles.SkeletonProgressContent}>
              <LoadingSkeleton
                width="100%"
                height="8px"
                variant="rounded"
                className={loadingStyles.SkeletonProgressBar}
              />
              <div className={loadingStyles.SkeletonProgressDetails}>
                <LoadingSkeleton width="80px" height="14px" />
                <LoadingSkeleton width="80px" height="14px" />
              </div>
            </div>
            <LoadingSkeleton width="32px" height="32px" variant="rounded" />
          </div>
        </div>
      </td>
    </tr>
  )
}

export default function BudgetsLoadingTable({
  isCustomerTable = false,
  customerTableLabel = 'Enterprise',
  isEnterpriseRoute = true,
  showScopeSelector = true,
  selectedScope = 'All',
}: Props) {
  return (
    <div className={styles.BudgetTableContainer}>
      <table className={styles.Table} data-hpc aria-label="Loading budgets">
        <thead className={styles.TableHeader}>
          <tr className={styles.TableRow}>
            <td className={styles.RowData}>
              <span className={styles.TableHeaderText}>
                {isCustomerTable ? `${customerTableLabel} budgets` : 'Budgets'}
              </span>
            </td>
            <td className={styles.ScopeSelector}>
              {!isCustomerTable && isEnterpriseRoute && showScopeSelector && (
                <ActionMenu>
                  <ActionMenu.Button variant="invisible" disabled>
                    <span className={styles.ScopeSelectorText}>Scope: {selectedScope}</span>
                  </ActionMenu.Button>
                </ActionMenu>
              )}
            </td>
          </tr>
        </thead>
        <tbody>
          {Array.from({length: SKELETON_ROW_COUNT}).map((_, index) => (
            // eslint-disable-next-line @eslint-react/no-array-index-key
            <SkeletonRow key={index} />
          ))}
        </tbody>
      </table>
    </div>
  )
}

try{ SkeletonRow.displayName ||= 'SkeletonRow' } catch {}
try{ BudgetsLoadingTable.displayName ||= 'BudgetsLoadingTable' } catch {}