import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'
import {Link} from '@primer/react'

import {ErrorComponent} from '..'

import {GROUP_BY_SKU_TYPE, Products} from '../../constants'
import type {UsagePeriod} from '../../enums'
import {RequestState} from '../../enums'
import {formatMoneyDisplay} from '../../utils/money'

import type {EnabledProduct} from '../../types/products'
import type {UsageLineItem} from '../../types/usage'
import useRoute from '../../hooks/use-route'
import {USAGE_ROUTE} from '../../routes'

import styles from './DefaultUsageCard.module.css'

interface DefaultUsageCardProps {
  isOrgAdmin: boolean
  product: EnabledProduct
  requestState: RequestState
  usage: UsageLineItem[]
  usagePeriod: UsagePeriod
}

const getBillableUsageDescription = (product: EnabledProduct): string => {
  switch (product.name) {
    case Products.actions:
      return 'Billable spend for Actions and Actions Runners for the selected timeframe. Applicable discounts cover Actions usage in public repositories and included usage for Actions minutes and storage.'
    case Products.git_lfs:
      return 'Billable spend for Git LFS for the selected timeframe. Applicable discounts cover included usage for Git LFS bandwidth and storage.'
    case Products.packages:
      return 'Billable spend for Packages for the selected timeframe. Applicable discounts cover Packages usage in public repositories and included usage for Packages data transfer and storage.'
    default:
      return `Billable spend for ${product.friendlyProductName} for the selected timeframe.`
  }
}

const isLoadingStates = new Set<RequestState>([RequestState.INIT, RequestState.LOADING])
export default function DefaultUsageCard({
  isOrgAdmin,
  product,
  requestState,
  usage,
  usagePeriod,
}: DefaultUsageCardProps) {
  const {path: usageUrl} = useRoute(
    USAGE_ROUTE,
    {},
    {
      group: GROUP_BY_SKU_TYPE.toString(),
      period: usagePeriod.toString(),
      query: `product:${product.name}`,
    },
  )

  const totalActual = usage.reduce((acc, lineItem) => acc + (lineItem.billedAmount ?? 0), 0)
  const totalDiscount = usage.reduce((acc, lineItem) => acc + (lineItem.discountAmount ?? 0), 0)
  const totalBilled = usage.reduce((acc, lineItem) => acc + (lineItem.totalAmount ?? 0), 0)

  return (
    <div className={styles.card}>
      <div className={styles.header}>
        <p className={styles.cardHeading}>Billable usage</p>
        <Link className={styles.link} inline href={usageUrl}>
          View details
        </Link>
      </div>
      <>
        <div className={styles.spendingContainer}>
          <div>
            {isLoadingStates.has(requestState) && (
              <LoadingSkeleton className={styles.loadingSkeleton} variant="rounded" height="61px" />
            )}
            {requestState === RequestState.ERROR && (
              <ErrorComponent
                sx={{border: 0}}
                testid={`${product.name}-usage-loading-error`}
                text="Something went wrong"
              />
            )}
            {requestState === RequestState.IDLE && (
              <TotalTextBox
                isOrgAdmin={isOrgAdmin}
                totalActual={totalActual}
                totalDiscount={totalDiscount}
                totalBilled={totalBilled}
              />
            )}
            <p className={styles.description} data-testid="billable-usage-description">
              {getBillableUsageDescription(product)}
            </p>
          </div>
        </div>
      </>
    </div>
  )
}

interface TotalTextBoxProps {
  isOrgAdmin: boolean
  totalActual: number
  totalDiscount: number
  totalBilled: number
}

function TotalTextBox({isOrgAdmin, totalActual, totalDiscount, totalBilled}: TotalTextBoxProps): React.ReactElement {
  if (isOrgAdmin) {
    return (
      <div className={styles.totalTextBox}>
        <span className={styles.totalTextMoneyDisplay}>{formatMoneyDisplay(totalActual)}</span>
        <span className={styles.orgAdminTotalTextDescription}>spent </span>
      </div>
    )
  }

  return (
    <div data-testid="billable-usage-money-display">
      <p className={styles.netAmountTextMoneyDisplay} data-testid="billable-usage-total">
        {totalBilled !== 0 ? (
          <span aria-label="Total billable usage after subtracting discounts from consumed usage" role="math">
            {formatMoneyDisplay(totalBilled)}
          </span>
        ) : (
          <>
            <span aria-describedby="billable-usage-zero-description">{formatMoneyDisplay(totalBilled)}</span>
            <span id="billable-usage-zero-description" className="sr-only">
              Total billable usage after subtracting discounts from consumed usage
            </span>
          </>
        )}
      </p>
      <div className={styles.totalTextBox} data-testid="billable-usage-formula">
        <span className={styles.formulaTextMoneyDisplay}>{formatMoneyDisplay(totalActual)}</span>
        <span className={styles.totalTextDescription}>consumed usage</span>
        <span
          className={styles.operator}
          role="math"
          aria-label="Minus"
          // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex
          tabIndex={0}
        >
          -
        </span>
        <span className={styles.formulaTextMoneyDisplay}>{formatMoneyDisplay(totalDiscount)}</span>
        <span className={styles.totalTextDescription}>discounts</span>
      </div>
    </div>
  )
}

try{ DefaultUsageCard.displayName ||= 'DefaultUsageCard' } catch {}
try{ TotalTextBox.displayName ||= 'TotalTextBox' } catch {}