import {Link, Button, Label} from '@primer/react'

import {formatMoneyDisplay} from '../../utils/money'
import {PageContext} from '../../App'
import {useContext} from 'react'

import styles from '../usage/SummaryCardContainer.module.css'

export interface NextPaymentCardProps {
  nextPaymentDate: string | null
  autoPayDisabled: boolean
  hasBill: boolean
  meteredViaAzure: boolean
  overdue: boolean
  latestBillAmount: number
  rbiPaymentLink: string
  nextChargeAmount: number
  entityLogin: string
}

const INDIA_RBI_DOC_LINK =
  'https://docs.github.com/billing/managing-the-plan-for-your-github-account/one-time-payments-for-customers-in-india'

export default function NextPaymentCard(props: NextPaymentCardProps) {
  const {isOrganizationRoute, isUserRoute, isStafftoolsRoute} = useContext(PageContext)
  const getPaymentHistoryLink = () => {
    if (isStafftoolsRoute) {
      return `/stafftools/users/${props.entityLogin}/history`
    }
    return isUserRoute ? '../account/billing/history' : '../billing/history'
  }
  return (
    <div className={styles.card} data-testid="next-payment-card">
      <div className={styles.header}>
        <p className={styles.heading}>Next payment due</p>

        {props.autoPayDisabled && props.nextChargeAmount > 0 ? (
          <>
            <div>
              <Button as="a" href={props.rbiPaymentLink} variant="primary" size="small">
                Pay now
              </Button>
            </div>
          </>
        ) : (
          <Link className={styles.link} href={getPaymentHistoryLink()} inline>
            Payment history
          </Link>
        )}
      </div>

      {
        <div className={styles.paymentContainer}>
          {!props.autoPayDisabled ? (
            <div>
              <p className={styles.moneyDisplayText} data-testid="next-payment-date">
                {props.nextChargeAmount > 0 ? props.nextPaymentDate || '-' : '-'}
              </p>
            </div>
          ) : (
            <div>
              <p className={styles.moneyDisplayText}>{formatMoneyDisplay(props.nextChargeAmount)} </p>
              <span className={styles.descriptionText}>
                {!props.overdue && props.nextChargeAmount > 0 && <> by {props.nextPaymentDate}</>}
              </span>
              <span>{props.overdue && <Label variant="attention">Overdue</Label>}</span>
            </div>
          )}
        </div>
      }

      <div className={styles.paymentDueContainer}>
        {props.meteredViaAzure && isOrganizationRoute && <p>Metered usage billed via Azure is not included.</p>}
        {props.autoPayDisabled && (
          <p>
            Automatic{' '}
            <Link inline href={INDIA_RBI_DOC_LINK} className={styles.descriptionText} target="_blank">
              recurring payments are disabled
            </Link>
            .
          </p>
        )}
      </div>
    </div>
  )
}

try{ NextPaymentCard.displayName ||= 'NextPaymentCard' } catch {}