import {GHAS_LICENSE_COST, GHEC_LICENSE_COST, HighWatermarkProducts, HighWatermarkSkus} from '../../../constants'
import type {Products} from '../../../constants'
import type {Product} from '../../../types/products'
import type {PricingDetails} from '../../../types/pricings'
import type {ProductSkuItem} from '../../../types/product-sku-item'
import {useCallback} from 'react'

interface Props {
  budgetValue: string
  enabledSkus: PricingDetails[]
  enabledProducts: Product[]
}

interface BudgetProductResult {
  selectedBudgetProduct: ProductSkuItem | null
  budgetProduct: string
  isHighWatermark: boolean
  isCopilotProduct: boolean
}

export function useBudgetProduct({budgetValue, enabledSkus, enabledProducts}: Props): BudgetProductResult {
  const findEnabledBudgetProduct = useCallback((): ProductSkuItem | null => {
    // Try to find in SKUs (these have real pricing data)
    const foundSku = enabledSkus?.find(sku => sku.sku === budgetValue)
    if (foundSku) {
      return {
        identifier: foundSku.sku,
        friendlyName: foundSku.friendlyName,
        price: foundSku.price,
        productType: foundSku.product as Products,
        isSku: true,
      }
    }

    // If not found in SKUs, try to find in products and add hardcoded pricing
    const foundProduct = enabledProducts.find(product => product.name === budgetValue)
    if (foundProduct) {
      let price: number | null = null

      // only look for GHAS and GHEC, because Copilot product has 1 > license SKU which means
      // that we can't assign it a single price
      switch (foundProduct.name) {
        case HighWatermarkProducts.ghas:
          price = GHAS_LICENSE_COST
          break
        case HighWatermarkProducts.ghec:
          price = GHEC_LICENSE_COST
          break
        default:
          price = null
      }

      return {
        identifier: foundProduct.name,
        friendlyName: foundProduct.friendlyProductName,
        price,
        productType: foundProduct.name as Products,
        isSku: false,
      }
    }

    return null
  }, [enabledSkus, budgetValue, enabledProducts])

  const selectedBudgetProduct = findEnabledBudgetProduct()
  const budgetProduct = selectedBudgetProduct?.identifier || budgetValue

  const isHighWatermark = useCallback(() => {
    return (
      Object.values(HighWatermarkProducts).includes(budgetProduct as HighWatermarkProducts) ||
      Object.values(HighWatermarkSkus).includes(budgetProduct as HighWatermarkSkus)
    )
  }, [budgetProduct])

  const isCopilotProduct = useCallback(() => {
    return budgetProduct === HighWatermarkProducts.copilot
  }, [budgetProduct])

  return {
    selectedBudgetProduct,
    budgetProduct,
    isHighWatermark: isHighWatermark(),
    isCopilotProduct: isCopilotProduct(),
  }
}
