import {Box} from '@primer/styled-react'
import styles from './UsageChart.module.css'

import {LoadingComponent} from '..'
import {boxStyle} from '../../utils/style'
import {getPeriodText, getUsageChartTitle} from '../../utils'

import type {Filters} from '../../types/usage'

const containerStyle = {
  ...boxStyle,
  width: '100%',
  height: '100%',
  p: 0,
  mb: 3,
}

const innerContainerStyle = {
  height: '432px',
  border: 0,
}

const chartHeaderContainerStyle = {
  display: 'flex',
  alignItems: 'center',
  pl: 3,
  pr: 3,
  pt: 3,
}

interface Props {
  premiumRequestsVariant?: boolean
  filters: Filters
}

export default function UsageChartSkeleton({premiumRequestsVariant, filters}: Props) {
  return (
    <Box sx={containerStyle}>
      <Box sx={chartHeaderContainerStyle}>
        <Box sx={{flex: 1}}>
          <h2 className={styles.chartTitle}>{getUsageChartTitle(filters, premiumRequestsVariant, {})}</h2>
          <span className={styles.chartSubtitle} data-testid="usage-chart-loading-message">
            {getPeriodText(filters.period)}
          </span>
        </Box>
      </Box>
      <LoadingComponent sx={innerContainerStyle} />
    </Box>
  )
}

try{ UsageChartSkeleton.displayName ||= 'UsageChartSkeleton' } catch {}