import {useState, useRef} from 'react'
import {Link, Button, Stack, Label, Dialog} from '@primer/react'
import {
  DiscountValueType,
  IncludedUsageDiscountTargetType,
  UsagePeriod,
  FundingSource,
  DiscountTarget,
} from '../../enums'
import {formatMoneyDisplay} from '../../utils/money'
import {
  getTextForIncludedUsageDiscount,
  getSubtextForDiscount,
  isIncludedUsageDiscount,
  isDiscountExpired,
} from '../../utils/discount'
import styles from './CurrentDiscountsListDialog.module.css'
import {getDaysUntilNextMonth} from '../../utils'
import type {DiscountStatesByTargetType, DiscountState} from '../../types/discounts'
import useRoute from '../../hooks/use-route'
import {USAGE_ROUTE} from '../../routes'
import {GROUP_BY_SKU_TYPE, Products} from '../../constants'

interface Props {
  discountStatesMap: DiscountStatesByTargetType
  discountStates: DiscountState[]
  totalDiscount: number
  isOrganization: boolean
  isUser: boolean
  isEnterpriseOrgOwner: boolean
  isCopilotPremiumUsageReportEnabled: boolean
}

const discountsListText = (isOrganization: boolean, isUser: boolean, isEnterpriseOrgOwner: boolean) => {
  const prefix = 'Showing currently applied usage and credits for your '

  if (isUser) {
    return `${prefix}account.`
  }
  if (isOrganization) {
    return `${prefix}organization.`
  }
  if (isEnterpriseOrgOwner) {
    return `${prefix}organization(s).`
  }
  return `${prefix}enterprise.`
}

const usagePeriodText = () => {
  const now = new Date()
  const monthAbbr = now.toLocaleString('en-US', {month: 'short'})
  const year = now.getFullYear()
  const lastDayOfMonth = new Date(year, now.getMonth() + 1, 0).getDate()
  const daysRemaining = getDaysUntilNextMonth()

  return `\nCurrent usage for ${monthAbbr} 1 - ${monthAbbr} ${lastDayOfMonth}, ${year}. Monthly quota resets in ${daysRemaining} day(s).`
}

// Helper to capitalize the first letter of each space-delimited token in the string
const capitalize = (s?: string): string => {
  return s ? s.replace(/\b\w/g, c => c.toUpperCase()) : ''
}

export default function CurrentDiscountsListDialog({
  discountStatesMap,
  discountStates,
  totalDiscount,
  isOrganization,
  isUser,
  isEnterpriseOrgOwner,
  isCopilotPremiumUsageReportEnabled,
}: Props) {
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const returnFocusRef = useRef(null)
  const discountsText = discountsListText(isOrganization, isUser, isEnterpriseOrgOwner)
  const {path: copilotUsageUrl} = useRoute(
    USAGE_ROUTE,
    {},
    {
      group: GROUP_BY_SKU_TYPE.toString(),
      period: UsagePeriod.THIS_MONTH.toString(),
      query: `product:${Products.copilot}`,
    },
  )

  const getLabels = (discountState: DiscountState) => {
    if (isIncludedUsageDiscount(discountState)) {
      return
    }

    return (
      <>
        {getLabelForFundingSource(discountState.discount?.fundingSource)}{' '}
        {isDiscountExpired(discountState) && <Label variant="danger">Expired</Label>}
      </>
    )
  }

  const buildDiscountItem = (discountState: DiscountState, discountText: string[]) => {
    const itemKey = discountState.discount?.uuid
    return (
      <div key={itemKey} data-testid={itemKey} className={styles.listItem}>
        <div className={styles.flexFill}>
          <p className={styles.discountText} key={discountText[0]}>
            {discountText[0]} {getLabels(discountState)}
          </p>
          <p className={styles.discountSubText} key={discountText[1]}>
            {discountText[1]}
          </p>
        </div>
        <p className={styles.discountAmount}>{formatMoneyDisplay(discountState.currentAmount)}</p>
      </div>
    )
  }

  const buildIncludedDiscountItem = (
    discountState: DiscountState,
    discountTargetType: IncludedUsageDiscountTargetType,
  ) => {
    const discountText = getTextForIncludedUsageDiscount(discountState, discountTargetType)
    return buildDiscountItem(discountState, discountText)
  }

  const buildIncludedDiscountItems = () => {
    const includedUsage: React.ReactNode[] = []

    for (const targetType of Object.values(IncludedUsageDiscountTargetType)) {
      const coercedTargetType = targetType as IncludedUsageDiscountTargetType
      if (!discountStatesMap[coercedTargetType]) continue

      const dollarDiscountStates = discountStatesMap[coercedTargetType]?.[DiscountValueType.Dollar]
      const percentageDiscountStates = discountStatesMap[coercedTargetType]?.[DiscountValueType.Percentage]

      if (dollarDiscountStates) {
        for (const discountState of dollarDiscountStates) {
          if (!isIncludedUsageDiscount(discountState)) continue

          const node = buildIncludedDiscountItem(discountState, coercedTargetType)
          includedUsage.push(node)
        }
      }

      if (percentageDiscountStates) {
        for (const discountState of percentageDiscountStates) {
          if (!isIncludedUsageDiscount(discountState)) continue

          const node = buildIncludedDiscountItem(discountState, coercedTargetType)
          includedUsage.push(node)
        }
      }
    }

    return includedUsage
  }

  const buildCreditItems = () => {
    const credits: React.ReactNode[] = []

    // Get the first day of the current month in UTC
    const now = new Date()
    const currentMonthStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1))

    for (const discountState of discountStates) {
      if (isIncludedUsageDiscount(discountState)) continue
      // Don't include credits that expired in a prior billing month
      if (isDiscountExpired(discountState)) {
        // Convert endDate from seconds to milliseconds and create Date object
        const discountEndDate = new Date(discountState.discount!.endDate * 1000)
        if (discountEndDate < currentMonthStart) {
          continue
        }
      }

      let primaryText: string
      let secondaryText: string

      if (discountState.discount?.targets[0] === undefined) {
        // This should never happen, but we need to handle it anyway
        primaryText = 'Unknown credit'
        secondaryText = 'Unknown amount'
        const node = buildDiscountItem(discountState, [primaryText, secondaryText])
        credits.push(node)
        continue
      }

      // For now, we only expect one target per credit
      switch (discountState.discount?.targets[0].type) {
        case DiscountTarget.Enterprise:
          primaryText = `Enterprise: ${capitalize(discountState.name)}`
          break
        case DiscountTarget.Organization:
          primaryText = `Organization: ${capitalize(discountState.name)}`
          break
        case DiscountTarget.Product:
          primaryText = `${capitalize(discountState.name)}`
          break
        case DiscountTarget.Repository:
          primaryText = `Repository: ${discountState.name}`
          break
        case DiscountTarget.SKU:
          // SKUs are snake-case
          primaryText = `${capitalize((discountState.name || '').replace(/_/g, ' '))}`
          break
        default:
          primaryText = `${capitalize(discountState.name)}`
      }

      const subtext = getSubtextForDiscount(discountState)
      const node = buildDiscountItem(discountState, [primaryText, subtext])
      credits.push(node)
    }

    return credits
  }

  const getLabelForFundingSource = (fundingSource?: FundingSource) => {
    let text: string | undefined

    switch (fundingSource) {
      case FundingSource.BillingCorrection:
        text = 'Billing correction'
        break
      case FundingSource.GitHubForStartups:
        text = 'GitHub for Startups'
        break
      case FundingSource.SocialImpact:
        text = 'Social Impact'
        break
      case FundingSource.Education:
        text = 'Education'
        break
      case FundingSource.OpenSource:
        text = 'Open Source'
        break
      case FundingSource.SalesOffer:
        text = 'Sales Offer'
        break
    }

    if (text) {
      return <Label variant="accent">{text}</Label>
    }
  }

  const includedDiscountItems = buildIncludedDiscountItems()
  const creditItems = buildCreditItems()

  return (
    <div data-testid="current-discounts-list-dialog-container">
      <Button variant="invisible" size="small" alignContent="center" onClick={() => setIsDialogOpen(true)}>
        More details
      </Button>

      {isDialogOpen && (
        <Dialog
          onClose={() => setIsDialogOpen(false)}
          title="Included usage and credits"
          returnFocusRef={returnFocusRef}
          aria-labelledby="header"
          className={styles.dialog}
        >
          <Stack className={styles.primaryStack}>
            <div className={styles.totalDiscount} data-testid="total-discount">
              {formatMoneyDisplay(totalDiscount)}
            </div>
            <div>
              <p className={styles.explanationText}>
                {discountsText}
                <br />
                {usagePeriodText()}
              </p>
            </div>
            <div className={styles.stackHeader}>
              <p>Included usage*</p>
            </div>
            <Stack className={styles.subStack}>{includedDiscountItems}</Stack>
            {creditItems.length > 0 && (
              <>
                <div className={styles.stackHeader}>
                  <p>Credits</p>
                </div>
                <Stack className={styles.subStack}>{creditItems}</Stack>
              </>
            )}
          </Stack>
          <div className={styles.footer}>
            <p className={styles.noteText}>* Included usage is an approximate amount based on current pricing.</p>

            {discountStatesMap[IncludedUsageDiscountTargetType.FREE_USAGE] && (
              <p className={styles.noteText} data-testid="free-usage-docs-link">
                ** GitHub Packages usage is free for public packages. For details on free Actions usage, see{' '}
                <Link
                  inline
                  href="https://docs.github.com/billing/concepts/product-billing/github-actions#free-use-of-github-actions"
                >
                  Free use of GitHub Actions
                </Link>
                .
              </p>
            )}

            {isCopilotPremiumUsageReportEnabled && (
              <p className={styles.noteText} data-testid="copilot-premium-usage-report-download">
                Download your Copilot premium request usage report{' '}
                <Link inline href={copilotUsageUrl}>
                  here
                </Link>
              </p>
            )}
          </div>
        </Dialog>
      )}
    </div>
  )
}

try{ CurrentDiscountsListDialog.displayName ||= 'CurrentDiscountsListDialog' } catch {}