import {useContext} from 'react'

import {PageContext} from '../../App'
import {DiscountUsageCard, EstimatedNextPaymentCard, TotalUsageCard} from '.'
import {useDiscounts} from '../../hooks/discount'
import {useTotalUsageData} from '../../hooks/usage'
import LatestInvoiceCard from '../invoices/LatestInvoiceCard'
import NextPaymentCard from '../payment_due/NextPaymentCard'
import PaymentDueCard from '../payment_due/PaymentDueCard'

import type {CustomerSelection} from '../../types/usage'
import type {EnabledProduct} from '../../types/products'
import type {LatestInvoiceCardProps} from '../invoices/LatestInvoiceCard'
import type {NextPaymentCardProps} from '../payment_due/NextPaymentCard'
import type {PaymentDueCardProps} from '../payment_due/PaymentDueCard'

import styles from './SummaryCardContainer.module.css'

interface Props {
  canViewDiscountUsage: boolean
  customerSelections: CustomerSelection[]
  enabledProducts: EnabledProduct[]
  isCopilotPremiumUsageReportEnabled: boolean
  isOnlyOrgAdmin: boolean
  latestInvoiceTileData: LatestInvoiceCardProps
  nextPaymentCardEnabled: boolean
  nextPaymentTileData: NextPaymentCardProps
  paymentDueTileData: PaymentDueCardProps
  showPaymentDueTile: boolean
  showLatestInvoiceTile: boolean
}

export default function SummaryCardContainer({
  canViewDiscountUsage,
  customerSelections,
  enabledProducts,
  isCopilotPremiumUsageReportEnabled,
  isOnlyOrgAdmin,
  latestInvoiceTileData,
  nextPaymentCardEnabled,
  nextPaymentTileData,
  paymentDueTileData,
  showPaymentDueTile,
  showLatestInvoiceTile,
}: Props) {
  const isStafftoolsRoute = useContext(PageContext).isStafftoolsRoute
  const isEnterpriseRoute = useContext(PageContext).isEnterpriseRoute
  const isNonEnterpriseRoute = !isEnterpriseRoute && !isStafftoolsRoute

  const {totalUsage, isLoadingTotalUsage, usageMap} = useTotalUsageData(customerSelections)
  const {discountStates, enabledProductDiscountStates, enabledProductDiscountTargetAmounts, isLoadingDiscounts} =
    useDiscounts({
      enabledProducts,
    })
  const totalDiscount = enabledProductDiscountStates.reduce((acc, discount) => acc + discount.currentAmount, 0)
  const estimatedNextPaymentValue = totalUsage - totalDiscount

  const showEstimatedNextPaymentCard = isEnterpriseRoute && !showPaymentDueTile && !showLatestInvoiceTile
  const showThreeColumnGrid =
    showPaymentDueTile || showLatestInvoiceTile || isNonEnterpriseRoute || showEstimatedNextPaymentCard

  return (
    <div
      className={[
        styles.summaryContainer,
        showThreeColumnGrid ? styles.threeColumnsWide : styles.twoColumnsWide,
        showEstimatedNextPaymentCard && styles.paymentCalculationGrid,
      ]
        .filter(Boolean)
        .join(' ')}
    >
      <TotalUsageCard totalUsage={totalUsage} usageMap={usageMap} isLoadingTotalUsage={isLoadingTotalUsage} />
      {canViewDiscountUsage && (
        <>
          {showEstimatedNextPaymentCard && (
            <span
              className={styles.operator}
              data-testid="minus-operator"
              role="math"
              aria-label="Minus"
              // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex
              tabIndex={0}
            >
              -
            </span>
          )}
          <DiscountUsageCard
            isEnterpriseOrgOwner={isOnlyOrgAdmin}
            isCopilotPremiumUsageReportEnabled={isCopilotPremiumUsageReportEnabled}
            isLoadingDiscounts={isLoadingDiscounts}
            totalDiscount={totalDiscount}
            discountTargetAmounts={enabledProductDiscountTargetAmounts}
            discountStates={discountStates}
          />
          {showEstimatedNextPaymentCard && (
            <>
              <span
                className={styles.operator}
                data-testid="equal-operator"
                role="math"
                aria-label="Equals"
                // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex
                tabIndex={0}
              >
                =
              </span>
              <EstimatedNextPaymentCard
                estimatedNextPaymentValue={estimatedNextPaymentValue}
                isLoadingValue={isLoadingTotalUsage || isLoadingDiscounts}
              />
            </>
          )}
        </>
      )}
      {showPaymentDueTile && <PaymentDueCard {...paymentDueTileData} />}
      {showLatestInvoiceTile && <LatestInvoiceCard {...latestInvoiceTileData} />}
      {(isNonEnterpriseRoute || (isStafftoolsRoute && nextPaymentCardEnabled)) && (
        <NextPaymentCard {...nextPaymentTileData} />
      )}
    </div>
  )
}

try{ SummaryCardContainer.displayName ||= 'SummaryCardContainer' } catch {}