import {useState, useMemo} from 'react'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'
import {isFeatureEnabled} from '@github-ui/feature-flags'

import useRequest from '../use-request'

import {ERRORS, BUDGETS_PAGE_SIZE} from '../../constants'
import {BUDGETS_ROUTE} from '../../routes'

import type {Budget, GetBudgetsLegacyResponse, GetBudgetsPaginatedResponse} from '../../types/budgets'
import {RequestState} from '../../enums'
import {BudgetType} from '../../enums/budgets'

interface UseBudgetsPageProps {
  page?: number
  pageSize?: number
  scope?: BudgetType | 'All' | 'customer'
  excludeScope?: 'enterprise' | 'customer'
  noop?: boolean
}

interface UseBudgetsPageReturn {
  budgets: Budget[]
  totalCount: number
  hasNextPage: boolean
  deleteBudgetFromPage: (uuid: string) => void
  requestState: RequestState
  isPaginationEnabled: boolean
}

const mapScopeToBackend = (scopeValue: BudgetType | 'All' | 'customer' | undefined): string | undefined => {
  if (!scopeValue || scopeValue === 'All') return undefined

  // Handle string literal 'customer'
  if (scopeValue === 'customer') return 'customer'

  const scopeMap: Record<string, string> = {
    [BudgetType.ORG]: 'org',
    [BudgetType.REPO]: 'repo',
    [BudgetType.COST_CENTER]: 'cost-center',
    [BudgetType.ENTERPRISE]: 'enterprise',
  }

  return scopeMap[scopeValue]
}

/**
 * @param props - Optional pagination and filter parameters
 * @returns Budgets data, pagination metadata, and helper functions
 */
function useBudgetsPage({
  page = 1,
  pageSize = BUDGETS_PAGE_SIZE,
  scope,
  excludeScope,
  noop = false,
}: UseBudgetsPageProps = {}): UseBudgetsPageReturn {
  const [budgets, setBudgets] = useState<Budget[]>([])
  const [totalCount, setTotalCount] = useState(0)
  const [hasNextPage, setHasNextPage] = useState(false)
  const [requestState, setRequestState] = useState<RequestState>(noop ? RequestState.IDLE : RequestState.INIT)
  const {addToast} = useToastContext()

  const isPaginationEnabled = isFeatureEnabled('billing_ui_budget_pagination_enabled')

  const reqParams = useMemo(() => {
    // If no scope is provided, don't send any params (legacy mode)
    if (!scope && !excludeScope && !isPaginationEnabled) {
      return undefined
    }

    const params: Record<string, string> = {}

    // Always include pagination params if pagination is enabled
    if (isPaginationEnabled) {
      params.page = String(page)
      params.page_size = String(pageSize)
    }

    const backendScope = mapScopeToBackend(scope)
    if (backendScope) {
      params.scope = backendScope
    }

    if (excludeScope) {
      params.exclude_scope = excludeScope
    }

    return Object.keys(params).length > 0 ? params : undefined
  }, [isPaginationEnabled, page, pageSize, scope, excludeScope])

  useRequest({
    route: BUDGETS_ROUTE,
    reqParams,
    noop,
    onStart: () => {
      setBudgets([])
      setRequestState(RequestState.LOADING)
    },
    onSuccess: response => {
      const payload = response.data.payload

      if (isPaginationEnabled) {
        const paginatedData = payload as GetBudgetsPaginatedResponse

        // Validate paginated response has required fields
        if (!Array.isArray(paginatedData.budgets)) {
          // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
          addToast({
            type: 'error',
            message: ERRORS.QUERY_BUDGETS_ERROR,
          })
          setRequestState(RequestState.ERROR)
          return
        }

        setBudgets(paginatedData.budgets)
        // If API doesn't return total_count, use the current budgets length as fallback
        setTotalCount(paginatedData.total_count ?? paginatedData.budgets.length)
        setHasNextPage(paginatedData.has_next_page ?? false)
      } else {
        const legacyData = payload as GetBudgetsLegacyResponse
        setBudgets(legacyData.budgets)
        setTotalCount(legacyData.budgets.length)
        setHasNextPage(false)
      }

      setRequestState(RequestState.IDLE)
    },
    onError: () => {
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({
        type: 'error',
        message: ERRORS.QUERY_BUDGETS_ERROR,
      })
    },
  })

  /**
   * @param uuid - The UUID of the budget to remove
   */
  function deleteBudgetFromPage(uuid: string) {
    const deleteIndex = budgets.findIndex(b => b.uuid === uuid)
    if (deleteIndex === -1) return

    const updatedBudgets = [...budgets]
    updatedBudgets.splice(deleteIndex, 1)

    setBudgets(updatedBudgets)

    if (isPaginationEnabled && totalCount > 0) {
      setTotalCount(totalCount - 1)
    }
  }

  return {budgets, totalCount, hasNextPage, deleteBudgetFromPage, requestState, isPaginationEnabled}
}

export default useBudgetsPage
