import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'
import {AlertIcon} from '@primer/octicons-react'
import {ProgressBar} from '@primer/react'

import styles from './PremiumUsageRequestsSummaryCard.module.css'
import {RequestState} from '../../../enums'
import {parseFormattedNumber} from '../../../utils/usage'

import type {ReactNode} from 'react'

interface PremiumUsageRequestSummaryCardProps {
  title: string
  value: string | number
  description: string | ReactNode
  testId?: string
  requestState: RequestState
  showProgressBar?: boolean
  entitlementValue?: number
}

export default function PremiumUsageRequestSummaryCard({
  title,
  value,
  description,
  testId,
  requestState,
  showProgressBar,
  entitlementValue,
}: PremiumUsageRequestSummaryCardProps) {
  const formattedValue = typeof value === 'number' ? value.toLocaleString() : value
  const formattedEntitlementValue = entitlementValue?.toLocaleString() || '0'
  const numericValue = typeof value === 'string' ? parseFormattedNumber(value) : value
  const progressPercentage = entitlementValue ? Math.min(((numericValue ?? 0) / entitlementValue) * 100, 100) : 0

  return (
    <div className={styles.summaryCard} data-testid={testId}>
      <p className={styles.cardTitle}>{title}</p>
      {requestState === RequestState.IDLE ? (
        <div className={styles.cardValueTextContainer}>
          <p className={styles.cardValue}>{formattedValue}</p>
          <p className={`${styles.entitlementText} ${showProgressBar ? '' : styles.entitlementTextHidden}`}>
            of {formattedEntitlementValue} included
          </p>
        </div>
      ) : requestState === RequestState.ERROR ? (
        <div className={styles.cardValueError}>
          <AlertIcon className="fgColor-danger" /> Something went wrong
        </div>
      ) : (
        <div className={styles.cardValue}>
          <LoadingSkeleton variant="rounded" size="titleMedium" width="100%" height="1.80rem" />
        </div>
      )}
      {showProgressBar && requestState === RequestState.IDLE && (
        <ProgressBar
          className={styles.progressBar}
          aria-label="Included premium requests progress"
          aria-valuetext={`${formattedValue} of ${formattedEntitlementValue} premium requests used`}
          bg="accent.emphasis"
          progress={progressPercentage}
          barSize="small"
        />
      )}
      <p className={styles.cardDescription}>{description}</p>
    </div>
  )
}

try{ PremiumUsageRequestSummaryCard.displayName ||= 'PremiumUsageRequestSummaryCard' } catch {}