import {useState, useMemo} from 'react'
import {Pagination, ActionMenu, ActionList} from '@primer/react'

import {BudgetType} from '../../enums/budgets'
import {BUDGETS_PAGE_SIZE} from '../../constants'

import {BudgetPricingTargetType, type Budget} from '../../types/budgets'
import BudgetData from './BudgetData'
import type {Product} from '../../types/products'
import type {PricingDetails} from '../../types/pricings'

import styles from './BudgetsTable.module.css'
import ServerSidePagination from '../common/ServerSidePagination'

type Props = {
  budgets: Budget[]
  deleteBudget: (budgetUuid: string) => void
  isCustomerTable?: boolean
  customerTableLabel?: string
  enabledProducts: Product[]
  enabledSkus: PricingDetails[]
  isEnterpriseRoute?: boolean
  hasBudgetWritePermissions?: boolean
  copilotIapSubscription: boolean
  isServerPagination?: boolean
  totalCount?: number
  currentPage?: number
  onPageChange?: (page: number) => void
  currentScope?: BudgetType | 'All'
  onScopeChange?: (scope: BudgetType | 'All') => void
  hasNextPage?: boolean
  hasPreviousPage?: boolean
}

export default function BudgetsTable({
  budgets,
  deleteBudget,
  isCustomerTable = false,
  customerTableLabel = 'Enterprise',
  enabledProducts,
  enabledSkus,
  isEnterpriseRoute = true,
  hasBudgetWritePermissions = false,
  copilotIapSubscription,
  isServerPagination = false,
  totalCount = 0,
  currentPage: externalCurrentPage = 1,
  onPageChange: externalOnPageChange,
  currentScope: _externalCurrentScope,
  onScopeChange: externalOnScopeChange,
  hasNextPage = false,
  hasPreviousPage = false,
}: Props) {
  const pageSize = BUDGETS_PAGE_SIZE
  const [internalCurrentPage, setInternalCurrentPage] = useState(1)
  const [internalSelectedIndex, setInternalSelectedIndex] = useState(0)
  const scopeTypes = ['All', 'Organizations', 'Repositories', 'Cost Centers']

  // Map scope string back to index for UI selection state
  const getIndexFromScope = (scope: BudgetType | 'All' | undefined): number => {
    switch (scope) {
      case BudgetType.ORG:
        return 1
      case BudgetType.REPO:
        return 2
      case BudgetType.COST_CENTER:
        return 3
      default:
        return 0 // 'All'
    }
  }

  // Use external scope for server pagination, internal for client pagination
  const selectedIndex = isServerPagination ? getIndexFromScope(_externalCurrentScope) : internalSelectedIndex
  const currentPage = isServerPagination ? externalCurrentPage : internalCurrentPage

  // Map scope index to scope string for server-side filtering
  const getScopeFromIndex = (index: number): BudgetType | 'All' => {
    switch (index) {
      case 1:
        return BudgetType.ORG
      case 2:
        return BudgetType.REPO
      case 3:
        return BudgetType.COST_CENTER
      default:
        return 'All'
    }
  }

  const filteredBudgets = useMemo(() => {
    // For server-side pagination, skip filtering - server already filtered
    if (isServerPagination) {
      return budgets
    }

    // For client-side pagination, filter locally
    let resourceType = 'All'
    switch (selectedIndex) {
      case 1: {
        resourceType = BudgetType.ORG
        break
      }
      case 2: {
        resourceType = BudgetType.REPO
        break
      }
      case 3: {
        resourceType = BudgetType.COST_CENTER
        break
      }
    }

    let filtered = resourceType !== 'All' ? budgets.filter(budget => budget.targetType === resourceType) : budgets

    // Filter by enabled products
    filtered = filtered.filter(budget => {
      if (budget.pricingTargetType !== BudgetPricingTargetType.ProductPricing) return true
      return enabledProducts.find(product => budget.pricingTargetId === product.name)
    })

    return filtered
  }, [isServerPagination, selectedIndex, budgets, enabledProducts])

  // Compute paged data and page count - using useMemo to avoid cascading renders
  const {pagedData, pageCount} = useMemo(() => {
    if (isServerPagination) {
      // Server-side pagination: display budgets as-is from server
      return {
        pagedData: filteredBudgets,
        pageCount: Math.ceil(totalCount / pageSize) || 1,
      }
    } else {
      // Client-side pagination: slice data locally
      return {
        pagedData: filteredBudgets.slice((currentPage - 1) * pageSize, currentPage * pageSize),
        pageCount: Math.ceil(filteredBudgets.length / pageSize) || 1,
      }
    }
  }, [filteredBudgets, currentPage, isServerPagination, totalCount, pageSize])

  const handleScopeChange = (index: number) => {
    if (isServerPagination && externalOnScopeChange) {
      // Server-side pagination: notify parent with scope string
      const scope = getScopeFromIndex(index)
      externalOnScopeChange(scope)
    } else {
      // Client-side pagination: update internal state and reset to page 1
      setInternalSelectedIndex(index)
      setInternalCurrentPage(1)
    }
  }

  const handlePageChange: Parameters<typeof Pagination>['0']['onPageChange'] = (e, page) => {
    e.preventDefault()
    if (isServerPagination && externalOnPageChange) {
      // Server-side pagination: notify parent
      externalOnPageChange(page)
    } else {
      // Client-side pagination: update internal state
      setInternalCurrentPage(page)
    }
  }

  const handleServerPageChange = (page: number) => {
    if (externalOnPageChange) {
      externalOnPageChange(page)
    }
  }

  return (
    <>
      <div className={styles.BudgetTableContainer}>
        <table className={styles.Table} data-hpc>
          <thead className={styles.TableHeader}>
            <tr className={styles.TableRow}>
              <td className={styles.RowData}>
                <span className={styles.TableHeaderText}>
                  {isCustomerTable
                    ? `${customerTableLabel} budgets`
                    : isServerPagination
                      ? 'Budgets'
                      : `${filteredBudgets.length} budgets`}
                </span>
              </td>
              <td className={styles.ScopeSelector}>
                {!isCustomerTable && isEnterpriseRoute && (
                  <ActionMenu>
                    <ActionMenu.Button variant="invisible">
                      <span className={styles.ScopeSelectorText}>Scope: {scopeTypes[selectedIndex] ?? 'All'}</span>
                    </ActionMenu.Button>
                    <ActionMenu.Overlay>
                      <ActionList>
                        <ActionList.Group selectionVariant="single">
                          <ActionList.GroupHeading>Filter scope</ActionList.GroupHeading>
                          {scopeTypes.map((scopeType, index) => (
                            <ActionList.Item
                              // eslint-disable-next-line @eslint-react/no-array-index-key
                              key={index}
                              selected={index === selectedIndex}
                              onSelect={() => handleScopeChange(index)}
                            >
                              {scopeType}
                            </ActionList.Item>
                          ))}
                        </ActionList.Group>
                      </ActionList>
                    </ActionMenu.Overlay>
                  </ActionMenu>
                )}
              </td>
            </tr>
          </thead>
          <tbody>
            {pagedData.length === 0 && isServerPagination ? (
              <tr>
                <td colSpan={2} className={styles.EmptyState}>
                  No budgets found for the selected scope
                </td>
              </tr>
            ) : (
              pagedData.map(budgetData => {
                return (
                  <BudgetData
                    key={budgetData.uuid}
                    budgetData={budgetData}
                    hasBudgetWritePermissions={hasBudgetWritePermissions}
                    deleteBudget={deleteBudget}
                    enabledProducts={enabledProducts}
                    enabledSkus={enabledSkus}
                    copilotIapSubscription={copilotIapSubscription}
                  />
                )
              })
            )}
          </tbody>
        </table>
      </div>

      {isServerPagination ? (
        <ServerSidePagination
          currentPage={currentPage}
          onPageChange={handleServerPageChange}
          hasNextPage={hasNextPage}
          hasPreviousPage={hasPreviousPage}
        />
      ) : (
        filteredBudgets.length > pageSize && (
          <Pagination pageCount={pageCount} currentPage={currentPage} onPageChange={handlePageChange} />
        )
      )}
    </>
  )
}

try{ BudgetsTable.displayName ||= 'BudgetsTable' } catch {}