import {ActionList, ActionMenu} from '@primer/react'
import {Box} from '@primer/styled-react'
import type {BetterSystemStyleObject} from '@primer/styled-react'

import {UsageSearchBar} from '.'
import styles from './UsageFilters.module.css'

import {
  GROUP_BY_SKU_TYPE,
  GROUP_BY_ORG_TYPE,
  GROUP_BY_REPO_TYPE,
  GROUP_BY_USER_TYPE,
  DEFAULT_GROUP_TYPE,
  DEFAULT_PREMIUM_REQUESTS_GROUP_TYPE,
  GROUP_BY_NONE_TYPE,
  GROUP_BY_MODEL_TYPE,
} from '../../constants'

import type {Customer} from '../../types/common'
import type {GroupSelection, PeriodSelection, Filters} from '../../types/usage'
import type {EnabledProduct} from '../../types/products'

const containerStyle = {
  display: 'flex',
  flexWrap: ['nowrap', 'nowrap', 'wrap'],
  flexDirection: ['column', 'column', 'row'],
  alignItems: 'stretch',
  mb: 3,
}

interface Props {
  customer: Customer
  filters: Filters
  setFilters: (filters: Filters) => void
  groupSelections?: GroupSelection[]
  periodSelections?: PeriodSelection[]
  showSearch?: boolean
  sx?: BetterSystemStyleObject
  enabledProducts?: EnabledProduct[]
  searchPlaceholder?: string
  premiumRequestsVariant?: boolean
  className?: string
  isCopilotStandalone?: boolean
  isEnterpriseOrgAdmin?: boolean
}

const DEFAULT_ENABLED_PRODUCTS: EnabledProduct[] = []

export default function UsageFilters({
  customer,
  filters,
  setFilters,
  // eslint-disable-next-line @eslint-react/no-unstable-default-props
  groupSelections = [],
  // eslint-disable-next-line @eslint-react/no-unstable-default-props
  periodSelections = [],
  showSearch = false,
  sx,
  enabledProducts = DEFAULT_ENABLED_PRODUCTS,
  searchPlaceholder,
  premiumRequestsVariant = false,
  className = '',
  isCopilotStandalone = false,
  isEnterpriseOrgAdmin = false,
}: Props) {
  const setSearchQuery = (query: string) => {
    setFilters({
      ...filters,
      searchQuery: query,
    })
  }

  const selectedGroupText = () => {
    return `Group by: ${filters.group?.displayText}`
  }

  const selectedPeriodText = () => {
    return `Timeframe: ${filters.period?.displayText}`
  }

  /**
   * Resets the group filter selection to the default group selection
   */
  const resetGroupFilterSelection = () => {
    // if the user is searching for a model, we want to default to the none group type
    const premiumRequestsFallback = filters.searchQuery.includes('model:')
      ? DEFAULT_GROUP_TYPE
      : DEFAULT_PREMIUM_REQUESTS_GROUP_TYPE

    setFilters({
      ...filters,
      group: groupSelections?.find(
        (obj: GroupSelection) => obj.type === (premiumRequestsVariant ? premiumRequestsFallback : DEFAULT_GROUP_TYPE),
      ),
    })
  }

  /**
   * Removes group by options from the dropdown based on the search query. For example,
   * if a user is searching for a particular SKU, group by product/SKU won't make much sense
   * so we remove the options.
   *
   * We also use this to avoid querying partitions that might not be in place yet.
   */
  const getGroupSelections = (): GroupSelection[] => {
    // filter out all options except for group by SKU and None when product is present
    if (filters.searchQuery.includes('product:')) {
      // eslint-disable-next-line react-hooks/immutability
      groupSelections = groupSelections.filter(
        group => group.type === GROUP_BY_SKU_TYPE || group.type === GROUP_BY_NONE_TYPE,
      )
    }

    // filter out all options except for None when sku is present
    if (filters.searchQuery.includes('sku:')) {
      groupSelections = groupSelections.filter(group => group.type === GROUP_BY_NONE_TYPE)
    }

    // filter out group by model and org when model is present
    if (filters.searchQuery.includes('model:')) {
      groupSelections = groupSelections.filter(
        group => group.type !== GROUP_BY_MODEL_TYPE && group.type !== GROUP_BY_ORG_TYPE,
      )
    }

    // filter out org/repo/user groupings if the user is searching for a specific org or repo or user
    if (
      filters.searchQuery.includes('org:') ||
      filters.searchQuery.includes('repo:') ||
      filters.searchQuery.includes('user:')
    ) {
      groupSelections = groupSelections.filter(
        group =>
          group.type !== GROUP_BY_ORG_TYPE && group.type !== GROUP_BY_REPO_TYPE && group.type !== GROUP_BY_USER_TYPE,
      )
    }

    // check if the current group selection exists in the filtered group selections, if it does not, we want to
    // fallback to the default selection as it was likely removed by the above
    const currentFilterGroupExists = groupSelections.some(group => group.type === filters.group?.type)
    if (!currentFilterGroupExists) {
      resetGroupFilterSelection()
    }

    return groupSelections
  }

  return (
    <Box
      sx={{
        ...containerStyle,
        ...sx,
      }}
      className={className}
      data-testid="usage-filters"
    >
      {showSearch && (
        <UsageSearchBar
          setSearchQuery={setSearchQuery}
          customer={customer}
          searchQuery={filters.searchQuery}
          selectedGroup={filters.group?.type}
          enabledProducts={enabledProducts}
          searchPlaceholder={searchPlaceholder}
          premiumRequestsVariant={premiumRequestsVariant}
          isCopilotStandalone={isCopilotStandalone}
          isEnterpriseOrgAdmin={isEnterpriseOrgAdmin}
        />
      )}

      {filters.group && (
        <Box
          sx={{
            ml: [0, 0, 2],
            mt: [2, 2, 0],
          }}
        >
          <ActionMenu>
            <ActionMenu.Button className={styles.filterButton}>{selectedGroupText()}</ActionMenu.Button>
            <ActionMenu.Overlay align="end">
              <ActionList selectionVariant="single" showDividers>
                {getGroupSelections().map(group => (
                  <ActionList.Item
                    key={group.type}
                    // reset the page param when changing group
                    onSelect={() => setFilters({...filters, group, page: 1})}
                    selected={group.type === filters.group?.type}
                  >
                    {group.displayText}
                  </ActionList.Item>
                ))}
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </Box>
      )}

      {filters.period && (
        <Box
          sx={{
            ml: [0, 0, 2],
            mt: [2, 2, 0],
          }}
        >
          <ActionMenu>
            <ActionMenu.Button className={styles.filterButton}>{selectedPeriodText()}</ActionMenu.Button>
            <ActionMenu.Overlay align="end">
              <ActionList selectionVariant="single" showDividers>
                {periodSelections.map(period => (
                  <ActionList.Item
                    key={period.type}
                    // reset the page param when changing period
                    onSelect={() => setFilters({...filters, period, page: 1})}
                    selected={period === filters.period}
                  >
                    {period.displayText}
                  </ActionList.Item>
                ))}
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </Box>
      )}
    </Box>
  )
}

try{ UsageFilters.displayName ||= 'UsageFilters' } catch {}