import {useState} from 'react'
import {Pagination} from '@primer/react'

import type {DiscountState} from '../../../types/discounts'
import {CreditData} from './CreditData'

import styles from './CreditsTable.module.css'

interface Props {
  credits: DiscountState[]
  deletedUuids: Set<string>
  deleteCredit?: (creditUuid: string) => void
}

export default function CreditsTable({credits, deletedUuids, deleteCredit}: Props) {
  const pageSize = 10
  const [currentPage, setCurrentPage] = useState(1)

  // Credits are already filtered at the page level
  const currData = credits

  // Calculate pagination data
  const pageNumber = Math.ceil(currData.length / (1.0 * pageSize)) || 1
  const pagedData = currData.slice((currentPage - 1) * pageSize, currentPage * pageSize)

  const onPageChange: Parameters<typeof Pagination>['0']['onPageChange'] = (e, page) => {
    e.preventDefault()
    setCurrentPage(page)
  }

  return (
    <>
      <div className={styles.CreditTableContainer}>
        <table className={styles.Table} data-hpc>
          <thead className={styles.TableHeader}>
            <tr className={styles.TableRow}>
              <th colSpan={6} className={styles.RowData}>
                <span className={styles.TableHeaderText}>{currData.length} credits</span>
              </th>
            </tr>
          </thead>
          <tbody>
            {pagedData.map(creditData => {
              const isDeleted = deletedUuids.has(creditData.uuid)
              return (
                <CreditData
                  key={creditData.uuid}
                  creditData={creditData}
                  isDeleted={isDeleted}
                  deleteCredit={deleteCredit}
                />
              )
            })}
          </tbody>
        </table>
        {currData.length === 0 && (
          <div className={styles.EmptyState}>
            <p>No credits found</p>
          </div>
        )}
      </div>
      {currData.length > pageSize && (
        <Pagination pageCount={pageNumber} currentPage={currentPage} onPageChange={onPageChange} />
      )}
    </>
  )
}

try{ CreditsTable.displayName ||= 'CreditsTable' } catch {}