import {ChevronLeftIcon, ChevronRightIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import {Box} from '@primer/styled-react'

type Props = {
  currentPage: number
  onPageChange: (page: number) => void
  hasNextPage?: boolean
  hasPreviousPage?: boolean
}

export default function ServerSidePagination({currentPage, onPageChange, hasNextPage, hasPreviousPage}: Props) {
  // If we don't have explicit hasNext/hasPrev, try to determine from other props
  const shouldShowPrevious = hasPreviousPage ?? currentPage > 1
  const shouldShowNext = hasNextPage ?? true

  // Don't render if we're on page 1 and there's no next page
  if (currentPage === 1 && !shouldShowNext) {
    return null
  }

  const handlePreviousClick = () => {
    if (shouldShowPrevious) {
      onPageChange(currentPage - 1)
    }
  }

  const handleNextClick = () => {
    if (shouldShowNext) {
      onPageChange(currentPage + 1)
    }
  }

  return (
    <Box
      sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 3,
        py: 3,
      }}
    >
      <Button
        variant="invisible"
        leadingVisual={ChevronLeftIcon}
        onClick={handlePreviousClick}
        disabled={!shouldShowPrevious}
        aria-label="Previous page"
      >
        Previous
      </Button>

      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          minWidth: 32,
          height: 32,
          borderRadius: '6px',
          backgroundColor: 'accent.emphasis',
          color: 'fg.onEmphasis',
          fontSize: 1,
          fontWeight: '600',
        }}
      >
        {currentPage}
      </Box>

      <Button
        variant="invisible"
        trailingVisual={ChevronRightIcon}
        onClick={handleNextClick}
        disabled={!shouldShowNext}
        aria-label="Next page"
      >
        Next
      </Button>
    </Box>
  )
}

try{ ServerSidePagination.displayName ||= 'ServerSidePagination' } catch {}