import {useNetUsageData} from '../../hooks/usage'
import {useBillableLicenses} from '../../hooks/use-billable-licenses'
import useCopilotUsageCardData from '../../hooks/usage/use-copilot-usage-card-data'

import UsageInfoTile, {UsageInfoTileTypes, UsageInfoTileVariant} from './UsageInfoTile'

import type {Filters, ProductUsageLineItem} from '../../types/usage'
import {useContext} from 'react'
import {PageContext} from '../../App'
import {Products} from '../../constants'
import {PRODUCT_TAB_TEXT_MAP, SKUs} from '../../constants/products'
import InfoIconOverlay from './InfoIconOverlay'
import useRoute from '../../hooks/use-route'
import {COPILOT_MANAGE_POLICIES_BASE_ROUTE_ORGS, COPILOT_MANAGE_POLICIES_BASE_ROUTE} from '../../routes'

import styles from './SeatBasedUsageContainer.module.css'

interface Props {
  filters: Filters
  isCopilotStandalone: boolean
  productName: string
  productCode: string
  trialCustomer?: boolean
}

export function SeatBasedUsageContainer({
  filters,
  isCopilotStandalone,
  productName,
  productCode,
  trialCustomer = false,
}: Props) {
  const isUserRoute = useContext(PageContext).isUserRoute
  const isEnterpriseRoute = useContext(PageContext).isEnterpriseRoute
  const isOrganizationRoute = useContext(PageContext).isOrganizationRoute
  const {path: copilotPoliciesUrl} = useRoute(COPILOT_MANAGE_POLICIES_BASE_ROUTE)
  const {path: organizationCopilotPoliciesUrl} = useRoute(COPILOT_MANAGE_POLICIES_BASE_ROUTE_ORGS)
  const {netUsage, requestState: netUsageRequestState} = useNetUsageData({filters})
  const {usageCardData} = useCopilotUsageCardData({filters})
  const totalSpend = netUsage.reduce((acc, lineItem) => acc + (lineItem.totalAmount ?? 0), 0)
  const today = new Date()
  const billableLicenses = useBillableLicenses({netUsage, filters, today})

  const premiumRequestSkus: string[] = []
  switch (productCode) {
    case Products.spark:
      premiumRequestSkus.push(SKUs.SparkPremiumRequestSku)
      break
    default: // Copilot as the default
      premiumRequestSkus.push(SKUs.CopilotPremiumRequestSku)
      premiumRequestSkus.push(SKUs.CodingAgentPremiumRequestSku)
      break
  }

  // For Copilot premium requests, use the net quantity from useCopilotUsageCardData
  // which already excludes discount usage
  const totalRequests =
    productCode === Products.copilot
      ? usageCardData.netQuantity
      : netUsage.reduce((acc, lineItem) => {
          const sku = (lineItem as ProductUsageLineItem).sku
          if (premiumRequestSkus.includes(sku)) {
            return acc + (lineItem.quantity ?? 0)
          }
          return acc
        }, 0)

  const overage = netUsage.reduce((acc, lineItem) => {
    const sku = (lineItem as ProductUsageLineItem).sku
    if (premiumRequestSkus.includes(sku)) {
      return acc + (lineItem.totalAmount ?? 0)
    }
    return acc
  }, 0)

  function determineCopilotPremiumRequestsUrl(
    isEnterprise: boolean,
    isOrganization: boolean,
    isUser: boolean,
    enterpriseRoute: string,
    organizationRoute: string,
  ) {
    if (isEnterprise) {
      const addPoliciesTab = `?tab=policies`
      const enterpriseCopilotPoliciesUrl = `${enterpriseRoute}${addPoliciesTab}`
      return enterpriseCopilotPoliciesUrl
    }

    if (isOrganization) {
      return organizationRoute
    }

    if (isUser) {
      return enterpriseRoute
    }
  }

  const shouldShowCopilotPremiumRequests = isCopilotStandalone || productCode === Products.copilot

  const showTrial =
    trialCustomer && (productName === PRODUCT_TAB_TEXT_MAP.ghec || productName === PRODUCT_TAB_TEXT_MAP.ghas)

  const overageMessage = `Cost calculated based on additional ${totalRequests} premium requests`

  const tiles = []
  switch (productCode) {
    case Products.copilot:
      tiles.push(
        <UsageInfoTile
          key="billableUsage"
          filters={filters}
          isCopilotStandalone={isCopilotStandalone}
          productName={productName}
          requestState={netUsageRequestState}
          totalSpend={totalSpend}
          variant={UsageInfoTileVariant.money}
          title={`${productName} usage`}
          subtitle={`Total spend on ${productName} for the selected timeframe, excluding applicable discounts.`}
          tileType={UsageInfoTileTypes.copilotUsage}
        />,
      )

      if (!isUserRoute) {
        tiles.push(
          <UsageInfoTile
            key="licenses"
            filters={filters}
            isCopilotStandalone={isCopilotStandalone}
            productName={productName}
            requestState={netUsageRequestState}
            totalQuantity={billableLicenses}
            title="Billable licenses"
            subtitle="Showing total unique licenses billed for your enterprise. Actual billed amount for each license is prorated based on when it is added during the billing cycle."
            infoIconOverlay={
              <InfoIconOverlay
                infoLabel="Billable licenses info"
                link="https://docs.github.com/enterprise-cloud@latest/billing/using-the-new-billing-platform/about-usage-based-billing-for-licenses"
                linkText="Learn more about billable licenses"
                overlayTitle="Billable licenses"
                overlayText={[
                  "If a user stops consuming a license within the month, the adjustment will be reflected in your next month's bill.",

                  "Billable licenses are only available for the 'Current month' timeframe.",
                ]}
              />
            }
            variant={UsageInfoTileVariant.quantity}
            tileType={UsageInfoTileTypes.copilotLicenses}
          />,
        )
      }

      if (shouldShowCopilotPremiumRequests) {
        tiles.push(
          <UsageInfoTile
            key="overage"
            filters={filters}
            isCopilotStandalone={isCopilotStandalone}
            productName={productName}
            requestState={netUsageRequestState}
            totalSpend={overage}
            totalQuantity={totalRequests}
            variant={UsageInfoTileVariant.money}
            title="Copilot premium requests"
            subtitle={overageMessage}
            infoIconOverlay={
              <InfoIconOverlay
                infoLabel="About Copilot premium requests"
                link={determineCopilotPremiumRequestsUrl(
                  isEnterpriseRoute,
                  isOrganizationRoute,
                  isUserRoute,
                  copilotPoliciesUrl,
                  organizationCopilotPoliciesUrl,
                )}
                linkText="Manage Copilot policy"
                overlayTitle="Copilot premium requests"
                overlayText={[
                  'If enabled, additional premium requests beyond the included amount for each license will be billed.',
                ]}
              />
            }
            tileType={UsageInfoTileTypes.copilotPremiumRequests}
          />,
        )
      }
      break
    case Products.models: {
      const totalQuantity = netUsage.reduce((acc, lineItem) => acc + (lineItem.quantity ?? 0), 0)
      tiles.push(
        <UsageInfoTile
          filters={filters}
          isCopilotStandalone={false}
          productName={productName}
          requestState={netUsageRequestState}
          totalSpend={netUsage.reduce((acc, lineItem) => acc + (lineItem.totalAmount ?? 0), 0)}
          totalQuantity={totalQuantity}
          variant={UsageInfoTileVariant.money}
          title="GitHub Models"
          subtitle={`Cost calculated based on additional ${totalQuantity} token units`}
          infoIconOverlay={
            <InfoIconOverlay
              infoLabel="About GitHub Models rate limits"
              link="https://docs.github.com/en/github-models/prototyping-with-ai-models#rate-limits"
              linkText="Learn more about GitHub Models rate limits"
              overlayTitle="GitHub Models rate limits"
              overlayText={[
                'The playground and free API usage are rate limited by requests per minute, requests per day, tokens per request, and concurrent requests.',
              ]}
            />
          }
          tileType={UsageInfoTileTypes.models}
        />,
      )
      break
    }
    case Products.spark:
      tiles.push(
        <UsageInfoTile
          key="overage"
          filters={filters}
          isCopilotStandalone={isCopilotStandalone}
          productName={productName}
          requestState={netUsageRequestState}
          totalSpend={overage}
          totalQuantity={totalRequests}
          variant={UsageInfoTileVariant.money}
          title={`Spark premium requests`}
          subtitle={`Cost calculated based on ${totalRequests} Spark premium requests that exceed the premium request usage included with your Copilot licenses.`}
          tileType={UsageInfoTileTypes.copilotPremiumRequests}
        />,
      )
      break
    default:
      tiles.push(
        <UsageInfoTile
          key="amount"
          filters={filters}
          isCopilotStandalone={isCopilotStandalone}
          productName={productName}
          requestState={netUsageRequestState}
          totalSpend={totalSpend}
          variant={UsageInfoTileVariant.money}
          title={`${productName} usage`}
          subtitle={`Total spend on ${productName} for the selected timeframe, excluding applicable discounts.`}
          showTrial={showTrial}
          tileType={UsageInfoTileTypes.generalAmount}
        />,
      )
      tiles.push(
        <UsageInfoTile
          key="licenses"
          filters={filters}
          isCopilotStandalone={isCopilotStandalone}
          productName={productName}
          requestState={netUsageRequestState}
          totalQuantity={billableLicenses}
          infoIconOverlay={
            <InfoIconOverlay
              infoLabel="Billable licenses info"
              link="https://docs.github.com/enterprise-cloud@latest/billing/using-the-new-billing-platform/about-usage-based-billing-for-licenses"
              linkText="Learn more about billable licenses"
              overlayTitle="Billable licenses"
              overlayText={[
                "If a user stops consuming a license within the month, the adjustment will be reflected in your next month's bill.",
                "Billable licenses are only available for the 'Current month' timeframe.",
              ]}
            />
          }
          title="Billable licenses"
          subtitle={
            showTrial
              ? 'Licenses will be shown here once billing starts.'
              : 'Showing total unique licenses billed for your enterprise. Actual billed amount for each license is prorated based on when it is added during the billing cycle.'
          }
          variant={UsageInfoTileVariant.quantity}
          showTrial={showTrial}
          tileType={UsageInfoTileTypes.generalLicenses}
        />,
      )
  }

  const columnCount = tiles.length
  const containerClass = columnCount === 1 ? '' : columnCount === 2 ? styles.twoColumns : styles.threeColumns

  return <div className={`${styles.gridColumns} ${containerClass}`}>{tiles}</div>
}

try{ SeatBasedUsageContainer.displayName ||= 'SeatBasedUsageContainer' } catch {}