import {useMemo} from 'react'
import type {ProductSkuItem} from '../../../types/product-sku-item'

interface UseLicenseCalculationsParams {
  budgetAmount: number | string
  selectedBudgetProduct: ProductSkuItem | null
  isCopilotProduct: boolean
  isHardLimitsEnabled: boolean
}

interface LicenseCalculationResult {
  licensesCount: number
  budgetDollarAmount: number
  shouldShowLicenseCount: boolean
  shouldShowBudgetAmount: boolean
}

export function useLicenseCalculations({
  budgetAmount,
  selectedBudgetProduct,
  isCopilotProduct,
  isHardLimitsEnabled,
}: UseLicenseCalculationsParams): LicenseCalculationResult {
  return useMemo(() => {
    if (!selectedBudgetProduct?.price) {
      return {
        licensesCount: 0,
        budgetDollarAmount: 0,
        shouldShowLicenseCount: false,
        shouldShowBudgetAmount: false,
      }
    }

    const licensesCount = isHardLimitsEnabled
      ? Number(budgetAmount)
      : Math.floor(Number(budgetAmount) / selectedBudgetProduct.price)

    const budgetDollarAmount = licensesCount * selectedBudgetProduct.price

    return {
      licensesCount,
      budgetDollarAmount,
      shouldShowLicenseCount: !isCopilotProduct,
      shouldShowBudgetAmount: isHardLimitsEnabled && !isCopilotProduct,
    }
  }, [budgetAmount, selectedBudgetProduct, isCopilotProduct, isHardLimitsEnabled])
}
