import {Label} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {useState} from 'react'

import type {DiscountState} from '../../../types/discounts'
import {DiscountTarget, DiscountType} from '../../../enums'
import {formatMoneyDisplay} from '../../../utils/money'
import {getLabelForFundingSource} from '../../../utils/FundingSource'
import CreditProgressBar from './CreditProgressBar'
import CreditActionMenu from './CreditActionMenu'
import useRoute from '../../../hooks/use-route'
import {DELETE_CREDIT_ROUTE} from '../../../routes'
import {doRequest, HTTPMethod} from '../../../hooks/use-request'

import styles from './CreditData.module.css'

interface Props {
  creditData: DiscountState
  isDeleted: boolean
  deleteCredit?: (creditUuid: string) => void
}

// Helper to capitalize the first letter of each space-delimited token in the string
const capitalize = (s?: string): string => {
  return s ? s.replace(/\b\w/g, c => c.toUpperCase()) : ''
}

const getFriendlyDiscountTypeName = (discountType?: DiscountType): string => {
  switch (discountType) {
    case DiscountType.NoDiscountType:
      return 'No Discount Type'
    case DiscountType.FixedAmount:
      return 'Fixed Amount'
    case DiscountType.Percentage:
      return 'Percentage'
    case DiscountType.RecurringFixedAmount:
      return 'Recurring Fixed Amount'
    default:
      return 'Unknown'
  }
}

export function CreditData({creditData, isDeleted, deleteCredit}: Props) {
  const [deleteStatus, setDeleteStatus] = useState<{type: 'success' | 'error'; message: string} | null>(null)
  const {path: deletePath} = useRoute(DELETE_CREDIT_ROUTE, {creditUUID: creditData.discount?.uuid || ''})
  const creditDefinition = creditData.discount

  async function handleDeleteCredit() {
    if (!creditDefinition?.uuid) return

    setDeleteStatus(null) // Clear any previous status

    try {
      const {ok, data} = await doRequest(HTTPMethod.DELETE, deletePath, {})
      if (ok) {
        deleteCredit?.(creditDefinition.uuid)
        setDeleteStatus({type: 'success', message: 'Credit deleted'})
      } else {
        setDeleteStatus({
          type: 'error',
          message: data.error ? data.error : 'Unable to delete credit',
        })
      }
    } catch {
      setDeleteStatus({type: 'error', message: 'Unable to delete credit'})
    }
  }

  let primaryText: React.ReactNode

  if (!creditDefinition || creditDefinition.targets[0] === undefined) {
    // This should never happen, but we need to handle it anyway
    primaryText = 'Unknown credit'
  } else {
    // For now, we only expect one target per credit
    switch (creditDefinition.targets[0].type) {
      case DiscountTarget.Enterprise:
        primaryText = 'Enterprise'
        break
      case DiscountTarget.Organization:
        primaryText = `Organization: ${capitalize(creditDefinition.targets[0].id)}`
        break
      case DiscountTarget.Product:
        primaryText = `Product: ${capitalize(creditDefinition.targets[0].id)}`
        break
      case DiscountTarget.Repository:
        primaryText = `Repository: ${creditDefinition.targets[0].id}`
        break
      case DiscountTarget.SKU:
        // SKUs are snake-case
        primaryText = `Sku: ${capitalize((creditDefinition.targets[0].id || '').replace(/_/g, ' '))}`
        break
      default:
        primaryText = `${capitalize(creditDefinition.targets[0].id)}`
    }
  }

  // Format dates using UTC to avoid hydration mismatches between server and client
  const formatDateUTC = (timestamp: number): string => {
    const date = new Date(timestamp * 1000)
    return date.toLocaleDateString('en-US', {timeZone: 'UTC'})
  }

  const startDate = creditDefinition ? formatDateUTC(creditDefinition.startDate) : 'N/A'
  const endDate = creditDefinition ? formatDateUTC(creditDefinition.endDate) : 'N/A'

  // Create utility function to check expiration
  const checkIfExpired = (endTimestamp: number): boolean => {
    const expirationDate = new Date(endTimestamp * 1000)
    const now = new Date()
    return expirationDate < now
  }

  const expired = creditDefinition ? checkIfExpired(creditDefinition.endDate) : false

  return (
    <>
      <tr className={styles.UuidRow}>
        <td colSpan={6} className={styles.UuidCell}>
          <span className={styles.UuidLabel}>UUID: {creditData.uuid}</span>
        </td>
      </tr>
      {deleteStatus && (
        <tr className={styles.UuidRow}>
          <td colSpan={6} className={styles.UuidCell}>
            <InlineMessage variant={deleteStatus.type === 'success' ? 'success' : 'critical'}>
              {deleteStatus.message}
            </InlineMessage>
          </td>
        </tr>
      )}
      <tr className={styles.CreditRow}>
        <td className={styles.TargetCell}>
          <div className={styles.TargetInfo}>
            <div className={styles.DataCell}>
              <span className={styles.CellLabel}>Scope</span>
              <span className={styles.CellValue}>{primaryText}</span>
              {isDeleted && (
                <div className={styles.Labels}>
                  <Label variant="danger">Deleted</Label>
                </div>
              )}
            </div>
          </div>
        </td>
        <td className={styles.TypeCell}>
          <div className={styles.DataCell}>
            <span className={styles.CellLabel}>Discount Type</span>
            <span className={styles.CellValue}>{getFriendlyDiscountTypeName(creditDefinition?.discountType)}</span>
          </div>
        </td>
        <td className={styles.ProgressCell}>
          <div className={styles.ProgressContainer}>
            <div className={styles.ProgressRow}>
              <div className={styles.ProgressContent}>
                {creditDefinition?.discountType === DiscountType.Percentage ? (
                  <div className={styles.PercentageDisplay}>
                    <span className={styles.PercentageAmount}>{creditDefinition.percentage}%</span>
                  </div>
                ) : (
                  <>
                    {creditDefinition && (
                      <CreditProgressBar
                        currentAmount={creditData.currentAmount}
                        targetAmount={creditDefinition.targetAmount}
                        data-testid="credit-progressbar"
                      />
                    )}
                    <div className={styles.ProgressDetails}>
                      <div>
                        <span className={styles.LinkText}>{formatMoneyDisplay(creditData.currentAmount)} used</span>
                      </div>
                      <div>
                        <span className={styles.LinkText}>
                          {creditDefinition ? formatMoneyDisplay(creditDefinition.targetAmount) : 'N/A'} total
                        </span>
                      </div>
                    </div>
                  </>
                )}
              </div>
            </div>
          </div>
        </td>
        <td className={styles.AmountCell}>
          <div className={styles.DataCell}>
            <span className={styles.CellLabel}>Start Date</span>
            <span className={styles.CellValue}>{startDate}</span>
          </div>
        </td>
        <td className={styles.AmountCell}>
          <div className={styles.DataCell}>
            <span className={styles.CellLabel}>End Date</span>
            <span className={styles.CellValue}>{endDate}</span>
            {expired && (
              <div className={styles.Labels}>
                <Label variant="danger">Expired</Label>
              </div>
            )}
          </div>
        </td>
        <td className={styles.StatusCell}>
          <div className={styles.DataCell}>
            <div>
              <span className={styles.CellLabel}>Funding Source</span>
              <span className={styles.CellValue}>
                {(creditDefinition && getLabelForFundingSource(creditDefinition.fundingSource)) || (
                  <Label variant="secondary">Not Specified</Label>
                )}
              </span>
            </div>
            {deleteCredit && creditDefinition?.uuid && (
              <CreditActionMenu
                creditId={creditDefinition.uuid}
                scope={String(primaryText)}
                onDeleteClick={handleDeleteCredit}
                disabled={!!(creditDefinition?.deletedAt && creditDefinition.deletedAt !== 0)}
              />
            )}
          </div>
        </td>
      </tr>
    </>
  )
}

try{ CreditData.displayName ||= 'CreditData' } catch {}