export function isDollarBasedDiscount(discountType: DiscountType) {
  const DOLLAR_BASED_DISCOUNT_TYPES: ReadonlySet<DiscountType> = new Set([
    DiscountType.FixedAmount,
    DiscountType.RecurringFixedAmount,
  ])

  return DOLLAR_BASED_DISCOUNT_TYPES.has(discountType)
}

export function isPercentageBasedDiscount(discountType: DiscountType) {
  const PERCENTAGE_BASED_DISCOUNT_TYPES: ReadonlySet<DiscountType> = new Set([DiscountType.Percentage])

  return PERCENTAGE_BASED_DISCOUNT_TYPES.has(discountType)
}

export function getTextForDiscount(
  discountAmount: DiscountState,
  targetType: IncludedUsageDiscountTargetType,
  discountType: DiscountType,
) {
  const {targetAmount, percentage} = discountAmount
  const isPremiumRequestDiscount = targetType === IncludedUsageDiscountTargetType.SKU_PREMIUM_REQUESTS

  let text: string[] | undefined = isPremiumRequestDiscount
    ? //  premium request included usage $ amount varies based on the quantity of the Copilot licenses so we use the general discount text logic
      undefined
    : DISCOUNT_TARGET_DATA_MAP[targetType]?.tiers[targetAmount]?.includedUsageModalText

  // If no discount tier-specific text was found, fall back to the general discount text
  if (!text) {
    text = INCLUDED_USAGE_DISCOUNT_TEXT_MAP[targetType]

    // premium request included usage $ amount varies based on the quantity of the Copilot licenses
    if (isPremiumRequestDiscount) {
      if (targetAmount > 0) {
        text[1] = `(~${formatMoneyDisplay(targetAmount)} off)`
      }
    } else {
      if (discountType === DiscountType.FixedAmount) {
        text[1] = `(${formatMoneyDisplay(targetAmount)} off)`
      }
      if (discountType === DiscountType.Percentage) {
        text[1] = `(${percentage}% off)`
      }

      text = [text.join(' ')]
    }
  }

  return text
}

// Shared helper to determine whether a discount should be treated as included usage or a credit
export function isIncludedUsageDiscount(discountState?: DiscountState) {
  return (
    discountState?.discount?.fundingSource === FundingSource.Plan ||
    discountState?.discount?.fundingSource === FundingSource.PublicRepository
  )
}

export function getSubtextForDiscount(discountState: DiscountState, isPremiumRequestDiscount: boolean = false) {
  // premium request included usage $ amount varies based on the quantity of the Copilot licenses
  if (isPremiumRequestDiscount) {
    return `~${formatMoneyDisplay(discountState.targetAmount)} off`
  }

  const discountType = discountState.discount?.discountType || DiscountType.NoDiscountType
  let subtext = ''

  switch (discountType) {
    case DiscountType.FixedAmount:
      subtext = `${formatMoneyDisplay(discountState.targetAmount)} off`
      break
    case DiscountType.RecurringFixedAmount:
      subtext = `${formatMoneyDisplay(discountState.targetAmount)} off per month`
      break
    case DiscountType.Percentage:
      subtext = `${discountState.discount?.percentage}% off per month`
      break
    default:
  }

  if (!isIncludedUsageDiscount(discountState)) {
    const rawEndDate = discountState.discount?.endDate
    if (rawEndDate != null) {
      const seconds = Number(rawEndDate)
      if (!isNaN(seconds)) {
        const endDate = new Date(seconds * 1000)
        const formattedEndDate = endDate.toLocaleString('en-US', {
          month: 'short',
          day: 'numeric',
          year: 'numeric',
        })
        subtext = `${subtext}, expires on ${formattedEndDate}`
      }
    }
  }

  return subtext
}

export function isDiscountExpired(discountState: DiscountState) {
  const rawEndDate = discountState.discount?.endDate
  if (rawEndDate != null) {
    const seconds = Number(rawEndDate)
    if (!isNaN(seconds)) {
      const endDate = new Date(seconds * 1000)
      const now = new Date()
      return endDate < now
    }
  }
  return false
}

export function getTextForIncludedUsageDiscount(
  discountState: DiscountState,
  targetType: IncludedUsageDiscountTargetType,
) {
  const {targetAmount} = discountState
  const isPremiumRequestDiscount = targetType === IncludedUsageDiscountTargetType.SKU_PREMIUM_REQUESTS

  let text: string[] | undefined = isPremiumRequestDiscount
    ? //  premium request included usage $ amount varies based on the quantity of the Copilot licenses so we use the general discount text logic
      undefined
    : DISCOUNT_TARGET_DATA_MAP[targetType]?.tiers[targetAmount]?.includedUsageModalText

  // If no discount tier-specific text was found, fall back to the general discount text
  if (!text) {
    text = INCLUDED_USAGE_DISCOUNT_TEXT_MAP[targetType]
    text[1] = getSubtextForDiscount(discountState, isPremiumRequestDiscount) || ''
  }

  return text
}

function targetsIncludeBothActionsAndPackagesStorage(targets: Target[]) {
  // return early if there are no targets or if the first target isn't one of the expected targets
  if (targets.length === 0 || (targets[0]?.id !== 'actions_storage' && targets[0]?.id !== 'packages_storage'))
    return false

  let includesActionsStorage = false
  let includesPackagesStorage = false
  for (const target of targets) {
    if (target.id === IncludedUsageDiscountTargetType.SKU_ACTIONS_STORAGE) {
      includesActionsStorage = true
    }

    if (target.id === IncludedUsageDiscountTargetType.SKU_PACKAGES_STORAGE) {
      includesPackagesStorage = true
    }
  }

  return includesActionsStorage && includesPackagesStorage
}

export function discountTargetToDiscountType(
  targetType: DiscountTarget,
  targetId: string,
  uuid: string,
  targets: Target[],
) {
  // Check for the combined actions/packages storage discount type
  if (targetType === DiscountTarget.SKU) {
    const areBothActionsAndPackagesStorage = targetsIncludeBothActionsAndPackagesStorage(targets)
    if (areBothActionsAndPackagesStorage) {
      return IncludedUsageDiscountTargetType.SKU_ACTIONS_PACKAGES_STORAGE_COMBINED
    }
  }

  switch (targetType) {
    case DiscountTarget.Enterprise:
      return IncludedUsageDiscountTargetType.ENTERPRISE
    case DiscountTarget.SKU:
      return SKU_DISCOUNTS_MAP[targetId] ?? IncludedUsageDiscountTargetType.UNSUPPORTED
    case DiscountTarget.Organization:
      return IncludedUsageDiscountTargetType.ORGANIZATION
    case DiscountTarget.Repository:
      return IncludedUsageDiscountTargetType.REPOSITORY
    case DiscountTarget.Product:
      return IncludedUsageDiscountTargetType.PRODUCT
    case DiscountTarget.NoDiscountTarget:
      return uuid === FREE_USAGE_DISCOUNT_UUID
        ? IncludedUsageDiscountTargetType.FREE_USAGE
        : IncludedUsageDiscountTargetType.UNSUPPORTED
    default:
      return IncludedUsageDiscountTargetType.UNSUPPORTED
  }
}

export function getUpdatedDiscountAmounts(data: DiscountState[]) {
  const updatedDiscountAmounts: DiscountStatesByTargetType = {}

  for (const discount of data) {
    // The assumption is that all targets are of the same type if there are multiple
    let {id: discountTargetId, type: discountTargetType} = (discount.targets[0] as Target) || {}

    // However for actions and packages storage, they can be combined into a single discount
    const areBothActionsAndPackagesStorageTargets = targetsIncludeBothActionsAndPackagesStorage(discount.targets)
    if (areBothActionsAndPackagesStorageTargets) {
      discountTargetId = IncludedUsageDiscountTargetType.SKU_ACTIONS_PACKAGES_STORAGE_COMBINED
      discountTargetType = DiscountTarget.SKU
    }
    const uuid = discount.uuid ?? ''
    const targetType = discountTargetToDiscountType(
      discountTargetType ?? DiscountTarget.NoDiscountTarget,
      discountTargetId ?? '',
      uuid,
      discount.targets,
    )
    if (targetType === IncludedUsageDiscountTargetType.UNSUPPORTED) continue

    updatedDiscountAmounts[targetType] ||= {}

    if (discount.percentage !== 0) {
      updatedDiscountAmounts[targetType][DiscountValueType.Percentage] ||= []
      updatedDiscountAmounts[targetType][DiscountValueType.Percentage]?.push(discount)
    } else {
      updatedDiscountAmounts[targetType][DiscountValueType.Dollar] ||= []
      updatedDiscountAmounts[targetType][DiscountValueType.Dollar]?.push(discount)
    }
  }

  return updatedDiscountAmounts
}
