import {useState} from 'react'
import {useNavigate} from '@github-ui/use-navigate'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {Banner} from '@primer/react'

import useRoute from '../../hooks/use-route'
import {BUDGETS_ROUTE, EDIT_BUDGET_ROUTE} from '../../routes'

import type {BudgetAlertDetails} from '../../types/budgets'

import styles from './BudgetBanner.module.css'

type BudgetBannerProps = {
  budgetAlertDetail: BudgetAlertDetails
}

export default function BudgetBanner({budgetAlertDetail}: BudgetBannerProps) {
  const navigate = useNavigate()
  const [visible, setVisible] = useState(true)

  const {text, variant, dismissible, dismiss_link: dismissLink, budget_id: budgetId} = budgetAlertDetail

  const handleDismiss = async () => {
    setVisible(false)
    await verifiedFetchJSON(dismissLink, {method: 'POST'})
  }

  const {path: editBudgetUrl} = useRoute(EDIT_BUDGET_ROUTE, {budgetUUID: budgetId})
  const {path: allBudgetsRoute} = useRoute(BUDGETS_ROUTE)
  const isSingleBudget = budgetId !== '' // budgetId is empty if the banner is associated with multiple budgets

  if (!visible) return null

  return (
    <Banner
      title="Billing budget alert"
      hideTitle
      description={text}
      variant={variant}
      primaryAction={
        isSingleBudget ? (
          <Banner.PrimaryAction onClick={() => navigate(editBudgetUrl)} data-testid="update-budget-button">
            Update your budget
          </Banner.PrimaryAction>
        ) : (
          <Banner.PrimaryAction onClick={() => navigate(allBudgetsRoute)} data-testid="view-budgets-button">
            View budgets
          </Banner.PrimaryAction>
        )
      }
      {...(dismissible && {onDismiss: handleDismiss})}
      className={styles.banner}
      data-testid="budget-banner"
    />
  )
}

try{ BudgetBanner.displayName ||= 'BudgetBanner' } catch {}