import {Link} from '@primer/react'

import {formatMoneyDisplay} from '../../utils/money'
import {LICENSING_BASE_ROUTE} from '../../routes'
import useRoute from '../../hooks/use-route'

import type {VolumeLicensesCardProps} from './VolumeLicensesCard'

import styles from './VolumeLicensesCard.module.css'

export default function VolumeLicensesCardCombined({gheAndGhas}: VolumeLicensesCardProps) {
  const {path: enterpriseLicensingPath} = useRoute(LICENSING_BASE_ROUTE, {}, {manage_seats: 'true'})
  return (
    <div className={styles.card} data-testid="volume-licenses-card-combined">
      <div className={styles.header}>
        <p className={styles.heading}>Spend on pre-purchased user licenses</p>

        <Link href={enterpriseLicensingPath} inline>
          Manage licenses
        </Link>
      </div>

      <div className={styles.moneyDisplayText}>
        {`${formatMoneyDisplay(gheAndGhas.spend)} `}
        <span className={styles.periodText}>{gheAndGhas.period}</span>
      </div>

      <p className={styles.description}>
        For <span className={styles.boldText}> GitHub Enterprise</span> and{' '}
        <span className={styles.boldText}>Advanced Security</span>.
      </p>
    </div>
  )
}

try{ VolumeLicensesCardCombined.displayName ||= 'VolumeLicensesCardCombined' } catch {}