import type {ReassignedResource} from '../../types/cost-centers'
import {ResourceType} from '../../enums/cost-centers'
import {LockIcon, RepoIcon} from '@primer/octicons-react'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {useState} from 'react'
import {Table, DataTable} from '@primer/react/experimental'
import {Text} from '@primer/styled-react'

interface Props {
  resources: ReassignedResource[]
}

export default function ReassignedResources({resources}: Props) {
  const resourcesToDisplay = resources.map(resource => ({
    id: resource.name,
    name: resource.name,
    type: resource.type,
    isPublic: resource.isPublic,
    avatarUrl: resource.avatarUrl,
    previousCostCenterName: resource.previousCostCenterName,
  }))

  const pageSize = 10
  const [page, setPage] = useState(0)
  const start = page * pageSize
  const end = start + pageSize
  const rows = resourcesToDisplay.slice(start, end)

  return (
    <Table.Container>
      <DataTable
        aria-labelledby="resources-pagination"
        data={rows}
        columns={[
          {
            header: 'Resource name',
            field: 'name',
            rowHeader: true,
            renderCell: resource => {
              let node: React.ReactNode

              switch (resource.type) {
                case ResourceType.Repo:
                  node = (
                    <>
                      {resource.isPublic ? <RepoIcon /> : <LockIcon />}
                      <Text as="span" sx={{ml: 1}}>
                        {resource.name}
                      </Text>
                    </>
                  )
                  break
                case ResourceType.Org:
                  node = (
                    <>
                      <GitHubAvatar src={resource.avatarUrl} size={16} />
                      <Text as="span" sx={{ml: 1}}>
                        {resource.name}
                      </Text>
                    </>
                  )
                  break
                case ResourceType.User:
                  node = (
                    <>
                      <GitHubAvatar src={resource.avatarUrl} size={16} />
                      <Text as="span" sx={{ml: 1}}>
                        {resource.name}
                      </Text>
                    </>
                  )
                  break
                default:
                  node = resource.name
              }
              return node
            },
          },
          {
            header: 'Resource type',
            field: 'type',
          },
          {
            header: 'Previous cost center',
            field: 'previousCostCenterName',
          },
        ]}
      />
      {resourcesToDisplay.length > pageSize && (
        <Table.Pagination
          aria-label="Pagination for reassigned resources"
          pageSize={pageSize}
          totalCount={resourcesToDisplay.length}
          onChange={({pageIndex}) => {
            setPage(pageIndex)
          }}
        />
      )}
    </Table.Container>
  )
}

try{ ReassignedResources.displayName ||= 'ReassignedResources' } catch {}